//! Payoff rules for one Pinky game. Integer maths only. These must match core/payoff.ts exactly;
//! tests/vectors.rs replays 2,880 golden vectors generated by the tested TypeScript rules.
use near_sdk::near;

pub const BPS: u128 = 10_000;

#[near(serializers = [json, borsh])]
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[serde(rename_all = "UPPERCASE")]
pub enum Move {
    Keep,
    Break,
}

impl Move {
    pub fn as_str(&self) -> &'static str {
        match self {
            Move::Keep => "KEEP",
            Move::Break => "BREAK",
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Params {
    pub rake_bps: u128,
    pub y_max_bps: u128,
    pub drip: u128,
    pub forfeit_bps: u128,
}

/// What one settled game pays out. jar_delta is negative when the Jar pays a bonus.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Settlement {
    pub player: u128,
    pub character: u128,
    pub jar_delta: i128,
    pub house: u128,
}

impl Settlement {
    /// player + character + jar_delta + house, which must equal 2 * stake.
    pub fn total(&self) -> i128 {
        self.player as i128 + self.character as i128 + self.jar_delta + self.house as i128
    }
}

pub fn validate(p: &Params) {
    assert!(p.rake_bps <= 2500, "rake_bps must be 0..2500");
    assert!(p.y_max_bps <= 10_000, "y_max_bps must be 0..10000");
    assert!(p.drip >= 2, "drip must be at least 2");
    assert!(p.forfeit_bps <= 5000, "forfeit_bps must be 0..5000");
}

/// Jar bonus each side gets when both keep: min(stake * y_max, jar / drip).
pub fn bonus(stake: u128, jar: u128, p: &Params) -> u128 {
    let cap = stake * p.y_max_bps / BPS;
    let share = jar / p.drip;
    if cap < share {
        cap
    } else {
        share
    }
}

pub fn settle(stake: u128, player: Move, character: Move, jar: u128, p: &Params) -> Settlement {
    let pot = 2 * stake;
    let fee = pot * p.rake_bps / BPS;
    match (player, character) {
        (Move::Keep, Move::Keep) => {
            let b = bonus(stake, jar, p);
            Settlement { player: stake + b, character: stake + b, jar_delta: -((2 * b) as i128), house: 0 }
        }
        (Move::Break, Move::Keep) => Settlement { player: pot - fee, character: 0, jar_delta: 0, house: fee },
        (Move::Keep, Move::Break) => Settlement { player: 0, character: pot - fee, jar_delta: 0, house: fee },
        (Move::Break, Move::Break) => Settlement { player: 0, character: 0, jar_delta: (pot - fee) as i128, house: fee },
    }
}

/// The character did not seal or reveal in time: the player takes both stakes, no rake.
pub fn settle_character_timeout(stake: u128) -> Settlement {
    Settlement { player: 2 * stake, character: 0, jar_delta: 0, house: 0 }
}

/// The player opened a game and never played: forfeit a share of the stake to the character.
pub fn settle_player_timeout(stake: u128, p: &Params) -> Settlement {
    let pen = stake * p.forfeit_bps / BPS;
    Settlement { player: stake - pen, character: stake + pen, jar_delta: 0, house: 0 }
}
